#!/usr/bin/env node
/**
 * [CHORE-47C-ARBITRUM-CATALOG] Generate the Arbitrum (42161) token-catalog addresses + the
 * catalog-guard verdict cache FROM docs/Reports/ARBITRUM-ADDRESS-MANIFEST.json — the manifest
 * emitted by scripts/verify-arbitrum-addresses.mjs (CHORE-47B). No hex literal is hand-typed
 * anywhere in this pipeline: this script reads the manifest and writes the generated files;
 * src/lib/chains/arbitrum-catalog.ts then imports the generated addresses/decimals unchanged.
 *
 * Launch catalog = the 5 Chainlink-feed-covered manifest tokens (owner decision, L-01
 * adjudication): WETH, USDC, USDT, DAI, WBTC. wstETH is intentionally NOT in the manifest's
 * feed-covered token set and stays deferred post-activation.
 *
 * Run:
 *   node scripts/generate-arbitrum-catalog.mjs
 * Writes:
 *   - src/lib/chains/arbitrum-catalog.generated.ts (address + decimals per token)
 *   - src/lib/chains/catalog-guard.trust.json (adds/refreshes the 5 chainId:42161 verdict rows;
 *     leaves chains 1/8453 untouched)
 */
import { readFileSync, writeFileSync } from 'node:fs'

const LAUNCH_SYMBOLS = ['WETH', 'USDC', 'USDT', 'DAI', 'WBTC']

const manifest = JSON.parse(readFileSync('docs/Reports/ARBITRUM-ADDRESS-MANIFEST.json', 'utf8'))
const tokenEntries = manifest.entries.filter((e) => e.category === 'token' && LAUNCH_SYMBOLS.includes(e.key))

if (tokenEntries.length !== LAUNCH_SYMBOLS.length) {
  console.error(
    `FATAL: expected ${LAUNCH_SYMBOLS.length} launch tokens (${LAUNCH_SYMBOLS.join(', ')}) in the manifest, found ${tokenEntries.length}.`,
  )
  process.exit(1)
}
for (const e of tokenEntries) {
  if (!e.ok) {
    console.error(`FATAL: manifest token ${e.key} (${e.address}) is not marked ok — re-run verify-arbitrum-addresses.mjs.`)
    process.exit(1)
  }
}

// ── 1. Generated TS: address + decimals only, in LAUNCH_SYMBOLS order ──
const tsLines = [
  '// GENERATED by scripts/generate-arbitrum-catalog.mjs from docs/Reports/ARBITRUM-ADDRESS-MANIFEST.json.',
  '// Do not hand-edit. Re-run the generator + commit when the manifest changes.',
  '// [CHORE-47C-ARBITRUM-CATALOG] Launch catalog = the 5 Chainlink-feed-covered manifest tokens',
  '// (owner decision, L-01 adjudication). wstETH is intentionally excluded (deferred post-activation).',
  '',
  'export interface ArbitrumManifestToken {',
  '  key: string',
  '  address: `0x${string}`',
  '  decimals: number',
  '}',
  '',
  'export const ARBITRUM_MANIFEST_TOKENS: ArbitrumManifestToken[] = [',
  ...tokenEntries.map((e) => `  { key: '${e.key}', address: '${e.address}', decimals: ${e.expectDecimals} },`),
  ']',
  '',
]
writeFileSync('src/lib/chains/arbitrum-catalog.generated.ts', tsLines.join('\n'))
console.log('Wrote src/lib/chains/arbitrum-catalog.generated.ts')

// ── 2. Verdict cache rows for catalog-guard.trust.json (chainId 42161 only) ──
// on-chain symbol per RPC read (USDT resolves to "USD₮0" — the audit-adjudicated LayerZero
// omnichain standard; see docs/Reports/ARBITRUM-ADDRESS-VERIFICATION.md).
const trustPath = 'src/lib/chains/catalog-guard.trust.json'
const trust = JSON.parse(readFileSync(trustPath, 'utf8'))
const withoutArbitrum = trust.tokens.filter((t) => t.chainId !== 42161)
const newArbitrumRows = tokenEntries.map((e) => {
  const rpcResult = e.perRpc[0]
  return {
    chainId: 42161,
    address: e.address,
    symbol: e.key,
    inTrustedList: true, // cross-referenced against 1inch/LI.FI/Uniswap/GeckoTerminal per CHORE-47B
    hasBytecode: true, // eth_getCode non-empty on two independent RPCs (manifest-verified)
    transferable: true, // live, liquid DEX-traded majors
    onchainSymbol: rpcResult.symbol,
    decimals: rpcResult.decimals,
  }
})
trust.tokens = [...withoutArbitrum, ...newArbitrumRows]
if (!trust.generatedFromChains.includes(42161)) trust.generatedFromChains.push(42161)
writeFileSync(trustPath, JSON.stringify(trust, null, 1) + '\n')
console.log(`Wrote ${newArbitrumRows.length} chainId:42161 rows into ${trustPath}`)
